/* Learning Data: "Pausa para pensar" de Security all the way through, en español. Mantén las claves iguales a think.en.js.
   La película se detiene al final de tres capítulos (who, checked, default), con una pregunta cada vez. think.js las muestra,
   y las lista otra vez en "Piénsalo" (#think-list). El "stop" de una pregunta es el lab de la serie que abre, en la página de labs de la
   serie; una pregunta sin él no tiene enlace a un lab. */
window.LEARN={lang:"es",
think:{ui:{toggle:"Pausa para pensar",kicker:"Pausa para pensar",cont:"Continuar",skip:"Saltar",lab:"Prueba la idea en un lab",off:"Desactivar las pausas",right:"Correcto.",wrong:"No del todo.",start:"Ver con pausas para pensar",answer:"Respuesta:",watch:"Ver esta parte"},
  qs:{
  who:{stop:"pass",q:"Ravi da a cada uno de los 47 trabajos su propia identidad, y a cada ejecución un salvoconducto de una hora. ¿Qué le da eso a la empresa?",
    opts:[{t:"Cada trabajo guarda su propia clave en su script, así que una clave copiada solo abre las tablas de ese trabajo.",near:true},{t:"Los trabajos leen más rápido, porque el catálogo ya no busca una cuenta que todos comparten."},{t:"Cada línea del registro nombra al trabajo que leyó, y no hay clave en un script que alguien pueda copiar.",ok:true}],
    why:"Una clave en un script sirve a quien la tenga, como la de data_loader; un salvoconducto en Hakone describía a la única mujer para la que era. Con su propia identidad, cada trabajo dice quién pregunta, así que cada línea del registro lo nombra, y el salvoconducto de cada ejecución dura una hora: no hay clave que guardar ni copiar. Una clave propia en un script todavía podría copiarla y usarla cualquiera. ¿Cuáles de tus trabajos corren todavía con una clave que alguien podría copiar?"},
  checked:{q:"Una laptop en la propia oficina de la empresa pide leer los datos bancarios de los clientes. ¿Qué pasa antes de leer una sola fila?",
    opts:[{t:"El catálogo revisa quién pregunta y qué puede hacer, igual que con una laptop en cualquier lugar.",ok:true},{t:"El catálogo la revisa la primera vez que pregunta, y luego confía en esa laptop el resto del día.",near:true},{t:"Está en la red de la propia empresa, así que puede leer los archivos bajo las tablas sin preguntar."}],
    why:"Estar en la red de la empresa no prueba nada: cada solicitud se revisa donde están los datos, cada vez, en el catálogo, que mira quién pregunta y qué puede hacer. Una laptop revisada una vez y luego de confianza sería una puerta abierta el resto del día. Y no hay senderos laterales: nadie lee los archivos bajo las tablas sin pasar por el catálogo. ¿Dónde podría alguien llegar a tus datos sin que lo revisen?"},
  default:{q:"¿Por qué cada trabajo nuevo parte de la plantilla de la plataforma, con su identidad, permisos, secretos y registro, en vez de que cada dominio arme el suyo?",
    opts:[{t:"Solo el equipo de la plataforma puede construir trabajos en ella, así que los dominios nunca escriben los suyos."},{t:"Si cada dominio decidiera, el camino rápido volvería a ganar, como con data_loader: la plantilla lo hace seguro.",ok:true},{t:"La plataforma revisa los pull requests en busca de claves, y solo en los trabajos hechos con su plantilla.",near:true}],
    why:"Nadie quiso hacer daño con data_loader: una cuenta nueva costaba un ticket y dos semanas, y la cuenta compartida funcionaba al instante. Si cada dominio decidiera, el camino rápido volvería a ganar. Por eso la plataforma hace fácil el camino seguro: un trabajo nuevo parte de una plantilla con su identidad, sus permisos, sus secretos y su registro desde el primer día, en minutos. Cada pull request también se revisa en busca de claves, todos, pero esa revisión sola no hace rápido el camino seguro. ¿Cuál es el camino rápido en tu plataforma, y es el seguro?"}
  }}};
